/**
 * MongoDB Node - Version 1.4
 * Discriminator: resource=document, operation=find
 */


interface Credentials {
  mongoDb: CredentialReference;
}

/** Find documents */
export type MongoDbV14DocumentFindParams = {
  resource: 'document';
  operation: 'find';
/**
 * MongoDB Collection
 */
    collection: string | Expression<string>;
/**
 * Add query options
 * @default {}
 */
    options?: {
    /** Use limit to specify the maximum number of documents or 0 for unlimited documents
     * @default 0
     */
    limit?: number | Expression<number>;
    /** The number of documents to skip in the results set
     * @default 0
     */
    skip?: number | Expression<number>;
    /** A JSON that defines the sort order of the result set
     * @default {}
     */
    sort?: IDataObject | string | Expression<string>;
    /** A JSON that defines a selection of fields to retrieve or exclude from the result set
     * @default {}
     */
    projection?: IDataObject | string | Expression<string>;
  };
/**
 * MongoDB find query in JSON format. Use $1, $2, and so on as complete values to reference Query Parameters below.
 * @hint Use query parameters for dynamic values instead of embedding expressions in the query
 * @default {}
 */
    query?: IDataObject | string | Expression<string>;
/**
 * JSON array of values to use for $1, $2, and so on, in order. Values can be strings, numbers, booleans, null, or arrays of these values. You can also use an expression that returns an array.
 * @hint For example, ["Alice", 30] replaces $1 with "Alice" and $2 with 30
 * @default []
 */
    queryParameters?: IDataObject | string | Expression<string>;
};

export type MongoDbV14DocumentFindNode = {
  type: 'n8n-nodes-base.mongoDb';
  version: 1.4;
  config: NodeConfig<MongoDbV14DocumentFindParams> & { credentials?: Credentials };
};